// Kinetic: rock-climbing page script (generated by kinetic-tools/build/build.py)
(function () {
  const PAGE = {
    key: "rock-climbing",
    v1: "Physics: nailed it 🧗",
    b1: "You've got the physics of climbing. Skim the chapters for anything you missed, then scroll to “Where to go” for gyms, boulders, crags and courses at your level. Knowing the science is a great start; it is not the same as being trained to belay, lead or place gear.",
    b2: "You have the basics. Fill the gaps below before your next session, especially the falls and anchors chapters: they're the ones that keep you and your partner safe.",
    b3: "No shame in that: this is exactly what the chapters are for. Read the ones linked below, then take the challenge again.",
    whereLabel: "Where to climb at my level →",
    disclaimer: "<strong>Self-check only.</strong> This quiz is a learning aid. It is not a certification, a belay check, a climbing grade or a qualification to lead, belay or place protection, and a high score does not make you safe on rock. Learn ropework only from a qualified instructor or a climbing gym's staff, pass the gym's own belay check, wear a helmet outdoors, and check every knot and harness with your partner before you leave the ground."
  };
  const CHAPTERS = {
    "ch-friction": "Ch 1 · Friction, rubber & rock",
    "ch-body":     "Ch 2 · Body position & torque",
    "ch-falls":    "Ch 3 · Ropes, falls & fall factor",
    "ch-anchors":  "Ch 4 · Anchors & protection",
    "ch-landing":  "Ch 5 · Bouldering falls & landings",
    "ch-energy":   "Ch 6 · Energy, grip & pump"
  };
  const QUESTIONS = [
    { ch: "ch-friction",
      q: "You stand on a smooth slab angled 45° from horizontal, all your weight on one shoe. What friction coefficient does the rubber need, at minimum, to stop you sliding?",
      o: ["About 0.1", "About 0.5", "About 1.0", "About 5"], a: 2,
      e: "On a slope at angle α, the shoe must supply friction of at least tan α times the normal force, so it needs μ ≥ tan 45° = 1.0. At 30° you need only 0.58. That's why slabs feel secure at low angles and suddenly desperate as they steepen." },
    { ch: "ch-friction",
      q: "Why do climbers prefer cool, dry mornings ('good conditions') for hard moves on small holds?",
      o: ["Sweat and heat reduce grip between skin, rubber and rock", "Rock gets heavier in the heat", "Gravity is weaker in the morning", "Ropes stretch less in the dark"], a: 0,
      e: "Sweaty, warm fingertips and soft, hot rubber slip more easily. Chalk (magnesium carbonate) absorbs sweat. Badami's own climbers start very early even in January, because direct sun makes holds and rubber greasy." },
    { ch: "ch-friction",
      q: "'Smearing' means pressing the sole of your shoe flat onto rock with no edge to stand on. What keeps it there?",
      o: ["Suction", "Glue in the rubber", "Magnetism", "Friction from pressing a large area of sticky rubber onto the rock, helped by keeping your weight over your feet"], a: 3,
      e: "Friction depends on how hard you press (the normal force) and the rubber's grip. Keeping your hips out from the wall and your weight over your feet increases the push into the rock; leaning in reduces it and your foot skates off." },
    { ch: "ch-body",
      q: "On a vertical wall, your arms mainly have to stop you toppling backwards. If you move your hips closer to the wall, the pull on your arms…",
      o: ["Decreases", "Increases", "Stays the same", "Becomes zero no matter what"], a: 0,
      e: "Your weight acts at your centre of mass. The further it is from the wall, the bigger the backward-toppling torque your arms must resist. In our worked example, moving the hips from 30 cm to 15 cm out halves the arm pull, from about 170 N to about 85 N." },
    { ch: "ch-body",
      q: "Why do coaches say 'climb with straight arms' when resting?",
      o: ["It looks better", "It makes you taller", "Hanging on straight arms lets bones and ligaments carry load instead of tiring muscles", "Bent arms are against the rules"], a: 2,
      e: "Holding a bent arm needs constant muscle tension (biceps and back). With arms straight, the skeleton takes much of the load, and your muscles can partly recover while your legs push." },
    { ch: "ch-falls",
      q: "A lead climber falls 3.5 m with 10 m of rope paid out between them and the belayer. What's the fall factor?",
      o: ["0.035", "0.35", "3.5", "35"], a: 1,
      e: "Fall factor = fall distance ÷ rope length available to absorb it = 3.5 ÷ 10 = 0.35. The higher the fall factor, the harder the catch, because less rope is stretching to absorb the same energy." },
    { ch: "ch-falls",
      q: "In the standard drop test that every single dynamic rope must pass (EN 892, required by UIAA 101), what's the maximum allowed peak force on the first drop?",
      o: ["1.2 kN", "12 kN", "120 kN", "There is no limit"], a: 1,
      e: "12 kN for single ropes, with an 80 kg mass in a factor-1.77 fall, and the rope must survive at least 5 drops. The test is deliberately extreme: in real falls, belayer movement, rope slip and your body all absorb energy, so forces are usually lower." },
    { ch: "ch-falls",
      q: "Why must you never lead climb on a 'static' (low-stretch) rope?",
      o: ["It's too heavy", "It's the wrong colour", "It can't be tied", "With little stretch to absorb the energy, the peak force in a fall can be dangerously high for you and the anchors"], a: 3,
      e: "A dynamic rope stretches several per cent to absorb a fall's energy over a longer distance. In our Fall Lab, swapping to a static rope roughly triples the peak force for the same fall. Static ropes are for abseiling, rescue and hauling, not for catching leader falls." },
    { ch: "ch-anchors",
      q: "Two bolts share a load through a sling. The angle between the sling legs is 120°. What share of the load does each bolt take?",
      o: ["About 25%", "About 50%", "About 100%: each bolt takes the full load", "Nothing"], a: 2,
      e: "Each leg carries F ÷ (2 cos(θ/2)). At 120°, cos 60° = 0.5, so each leg takes 1.0 × F. Keep anchor angles narrow (under about 60°, where each leg takes about 58%) so the load really is shared." },
    { ch: "ch-anchors",
      q: "In traditional ('trad') climbing, what holds a spring-loaded camming device in a crack when you fall on it?",
      o: ["Glue", "Its weight", "Rope tension pulls the cams wider, pressing outward on the crack walls and creating friction", "A bolt hidden inside"], a: 2,
      e: "Pull on the stem and the lobes rotate outward, pushing on the crack walls; the harder you pull, the harder they push, and friction holds them. That only works in solid rock of the right shape. Soft or crumbly rock, or a flaring crack, can let it rip out." },
    { ch: "ch-landing",
      q: "You drop from 3 m onto a crash pad that compresses 30 cm as you stop. Roughly what's your average deceleration?",
      o: ["About 10 g", "About 1 g", "About 100 g", "About 0.1 g"], a: 0,
      e: "Speed at impact = √(2 × 9.81 × 3) ≈ 7.7 m/s. Stopping over 0.3 m: a = v² ÷ (2d) ≈ 98 m/s² ≈ 10 g. Bend your knees and roll as you land, and the stopping distance grows, so the deceleration falls." },
    { ch: "ch-landing",
      q: "What is a 'spotter' for in bouldering?",
      o: ["To guide the falling climber's body (especially head and back) onto the pad and away from hazards", "To catch the climber in their arms", "To film the climb", "To push the climber up the wall"], a: 0,
      e: "A spotter doesn't catch you; they steer you. Hands up, aiming at your hips and back, they help you land feet-first on the pad and stop you tipping back onto your head or into rocks." },
    { ch: "ch-landing",
      q: "Doubling the height you fall from (say from 2 m to 4 m) does what to your impact speed?",
      o: ["Doubles it", "Quadruples it", "Leaves it unchanged", "Raises it by about 41% (√2)"], a: 3,
      e: "v = √(2gh), so speed scales with the square root of height: √2 ≈ 1.41. But the energy you have to absorb doubles (mgh), which is why highball boulders need more pads, more spotters and careful landings." },
    { ch: "ch-energy",
      q: "A 70 kg climber climbs a 20 m route. How much mechanical work did they do just lifting their body?",
      o: ["About 1.4 kJ", "About 14 kJ", "About 140 kJ", "About 1,400 kJ"], a: 1,
      e: "Work = m × g × h = 70 × 9.81 × 20 ≈ 13.7 kJ (about 3.3 kcal). Your body burns several times that, because muscles are inefficient and much effort goes into gripping and stabilising, not lifting." },
    { ch: "ch-energy",
      q: "What causes the 'pump', when your forearms swell and your grip fades on a long route?",
      o: ["The rope pulling on your harness", "Sustained hard gripping squeezes the blood vessels in your forearm muscles, starving them of oxygen while waste products build up", "Low air pressure", "Too much chalk"], a: 1,
      e: "Hard, continuous gripping restricts blood flow through the forearm muscles. Shaking out on good holds and climbing efficiently, not just harder, let blood flow back. Pacing and good footwork are the real antidote." }
  ];

  // ---------- QUIZ RENDER ----------
  const list = document.getElementById("quiz-list");
  const dots = document.getElementById("quiz-dots");
  const prog = document.getElementById("quiz-progress");
  const progLabel = document.getElementById("quiz-progress-label");
  const warn = document.getElementById("quiz-warn");
  const resultBox = document.getElementById("quiz-result");
  let graded = false;

  function esc(s) { return s.replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

  QUESTIONS.forEach((item, i) => {
    const n = i + 1;
    const div = document.createElement("div");
    div.className = "q";
    div.id = "q" + n;
    div.dataset.index = i;
    div.innerHTML =
      `<span class="qtag">${esc(CHAPTERS[item.ch].split(" · ")[1])}</span>` +
      `<span class="qnum">Question ${n} / ${QUESTIONS.length}</span>` +
      `<h3>${esc(item.q)}</h3>` +
      `<div class="opts" role="radiogroup" aria-label="Question ${n}">` +
      item.o.map((opt, j) =>
        `<label class="opt"><input type="radio" name="q${n}" value="${j}"><span>${esc(opt)}</span><span class="mark"></span></label>`
      ).join("") +
      `</div><div class="explain" aria-live="polite"></div>`;
    list.appendChild(div);

    const d = document.createElement("a");
    d.href = "#q" + n; d.textContent = n; d.id = "dot" + n;
    d.setAttribute("aria-label", "Go to question " + n);
    dots.appendChild(d);
  });

  function answeredCount() {
    return QUESTIONS.filter((_, i) => document.querySelector(`input[name="q${i + 1}"]:checked`)).length;
  }
  function updateProgress() {
    const c = answeredCount();
    prog.style.width = (c / QUESTIONS.length * 100) + "%";
    progLabel.textContent = `${c} of ${QUESTIONS.length} answered`;
  }

  list.addEventListener("change", (ev) => {
    if (graded || ev.target.type !== "radio") return;
    const q = ev.target.closest(".q");
    q.querySelectorAll(".opt").forEach(l => l.classList.toggle("sel", l.querySelector("input").checked));
    document.getElementById("dot" + (+q.dataset.index + 1)).classList.add("answered");
    updateProgress();
    warn.style.display = "none";
  });

  function grade() {
    const unanswered = QUESTIONS.length - answeredCount();
    if (unanswered > 0 && !document.getElementById("quiz-submit").dataset.confirmed) {
      warn.textContent = `${unanswered} question${unanswered > 1 ? "s" : ""} unanswered. They'll count as wrong. Press submit again to score anyway.`;
      warn.style.display = "block";
      document.getElementById("quiz-submit").dataset.confirmed = "1";
      return;
    }
    graded = true;
    let score = 0;
    const wrongChapters = new Map();
    QUESTIONS.forEach((item, i) => {
      const n = i + 1;
      const qEl = document.getElementById("q" + n);
      const picked = document.querySelector(`input[name="q${n}"]:checked`);
      const pickedIdx = picked ? +picked.value : -1;
      const right = pickedIdx === item.a;
      if (right) score++;
      else wrongChapters.set(item.ch, (wrongChapters.get(item.ch) || []).concat(n));
      qEl.classList.add("graded", right ? "right" : (picked ? "wrong" : "skipped"));
      qEl.querySelectorAll("input").forEach(inp => inp.disabled = true);
      qEl.querySelectorAll(".opt").forEach((lab, j) => {
        if (j === item.a) { lab.classList.add("correct"); lab.querySelector(".mark").textContent = "✓ correct"; }
        else if (j === pickedIdx) { lab.classList.add("incorrect"); lab.querySelector(".mark").textContent = "✗ your pick"; }
      });
      const ex = qEl.querySelector(".explain");
      ex.innerHTML = `<span class="verdict">${right ? "Correct." : (picked ? "Not quite." : "Skipped.")}</span> ${esc(item.e)}` +
        (right ? "" : `<br><a class="chlink" href="#${item.ch}" data-wrong-link="${item.ch}">Read ${esc(CHAPTERS[item.ch])} →</a>`);
      const dot = document.getElementById("dot" + n);
      dot.classList.remove("answered"); dot.classList.add(right ? "right" : "wrong");
    });

    const pct = score / QUESTIONS.length;
    let lvl, title, blurb;
    if (pct >= 0.8) { lvl = "lvl-ready"; title = PAGE.v1; blurb = PAGE.b1; }
    else if (pct >= 0.55) { lvl = "lvl-close"; title = "Nearly there. Brush up on a couple of chapters"; blurb = PAGE.b2; }
    else { lvl = "lvl-brush"; title = "Brush up first"; blurb = PAGE.b3; }

    resultBox.className = "result show " + lvl;
    const chItems = [...wrongChapters.entries()].map(([ch, qs]) =>
      `<li><a href="#${ch}" data-summary-link="${ch}">${esc(CHAPTERS[ch])}</a> <span class="small">(question${qs.length > 1 ? "s" : ""} ${qs.join(", ")})</span></li>`).join("");
    resultBox.innerHTML =
      `<div class="score" id="quiz-score">${score}<small> / ${QUESTIONS.length}</small></div>` +
      `<h3 id="quiz-verdict">${title}</h3><p>${blurb}</p>` +
      `<div class="result-note" id="quiz-disclaimer" role="note">${PAGE.disclaimer}</div>` +
      (chItems ? `<strong>Chapters to read:</strong><ul id="quiz-revisit">${chItems}</ul>` : `<p><strong>Perfect score.</strong> The chapters still have the worked numbers if you want to go deeper.</p>`) +
      `<div class="actions"><button class="btn btn-ghost" type="button" id="quiz-retake">↺ Retake the challenge</button><a class="btn btn-ghost" href="#where">${PAGE.whereLabel}</a></div>`;
    document.getElementById("quiz-retake").addEventListener("click", resetQuiz);
    document.getElementById("quiz-submit").style.display = "none";
    warn.style.display = "none";
    resultBox.scrollIntoView({ behavior: "smooth", block: "start" });
    try { localStorage.setItem("kinetic-" + PAGE.key + "-last", JSON.stringify({ score, of: QUESTIONS.length, at: Date.now() })); } catch (e) {}
  }

  function resetQuiz() {
    graded = false;
    resultBox.className = "result"; resultBox.innerHTML = "";
    document.querySelectorAll(".q").forEach(q => {
      q.className = "q";
      q.querySelector(".explain").innerHTML = "";
      q.querySelectorAll("input").forEach(i => { i.checked = false; i.disabled = false; });
      q.querySelectorAll(".opt").forEach(l => { l.className = "opt"; l.querySelector(".mark").textContent = ""; });
    });
    document.querySelectorAll("#quiz-dots a").forEach(d => d.className = "");
    const sub = document.getElementById("quiz-submit");
    sub.style.display = ""; delete sub.dataset.confirmed;
    updateProgress();
    document.getElementById("q1").scrollIntoView({ behavior: "smooth", block: "start" });
  }

  document.getElementById("quiz-submit").addEventListener("click", grade);
  document.getElementById("quiz-reset").addEventListener("click", resetQuiz);
  updateProgress();

  // Expose for automated tests
  window.KINETIC_QUIZ = { QUESTIONS, CHAPTERS, grade, resetQuiz };


  // ---------- FALL LAB ----------
  // Ideal spring rope: F = mg(1 + sqrt(1 + 2 f EA / mg)); EA ≈ 24 kN dynamic (80 kg at f 1.77 → ≈ 9 kN), 250 kN "static" (illustrative).
  // Fall = 2 × height above last bolt + slack; top-bolt load ≈ 1.6 × peak (illustrative friction over the carabiner).
  (function () {
    const $ = id => document.getElementById(id);
    if (!$("rc-mass")) return;
    let slack = 0.5, EA = 24000;
    const g = 9.81;
    function update() {
      const m = +$("rc-mass").value, out = +$("rc-out").value, above = +$("rc-above").value;
      $("rc-mass-o").textContent = m + " kg";
      $("rc-out-o").textContent = out + " m";
      $("rc-above-o").textContent = above.toFixed(1) + " m";
      const fall = 2 * above + slack, f = fall / out, mg = m * g;
      const F = mg * (1 + Math.sqrt(1 + 2 * f * EA / mg));
      const stretch = (F - mg) / (EA / out);
      $("rc-fall").textContent = fall.toFixed(1) + " m";
      $("rc-ff").textContent = f.toFixed(2);
      $("rc-v").textContent = Math.sqrt(2 * g * fall).toFixed(1) + " m/s";
      $("rc-peak").textContent = (F / 1000).toFixed(1) + " kN";
      $("rc-peak").style.color = F > 12000 ? "#ff8a70" : (F > 8000 ? "#ffd27a" : "#fff");
      $("rc-peak-s").textContent = F > 12000 ? "over the 12 kN rope-test limit" : (EA > 100000 ? "static rope: very hard catch" : "Ch 3 · ideal spring rope");
      $("rc-g").textContent = (F / mg).toFixed(1) + " ×";
      $("rc-stretch").textContent = stretch.toFixed(2) + " m";
      $("rc-bolt").textContent = "≈ " + (1.6 * F / 1000).toFixed(1) + " kN";
      $("rc-bar").style.width = Math.min(100, F / 12000 * 100).toFixed(0) + "%";
    }
    ["rc-mass", "rc-out", "rc-above"].forEach(id => $(id).addEventListener("input", update));
    function seg(id, fn) {
      document.querySelectorAll("#" + id + " button").forEach(b => b.addEventListener("click", () => {
        fn(b);
        document.querySelectorAll("#" + id + " button").forEach(x => x.setAttribute("aria-pressed", x === b ? "true" : "false"));
        update();
      }));
    }
    seg("rc-slack", b => { slack = +b.dataset.m; });
    seg("rc-rope", b => { EA = +b.dataset.ea; });
    update();
  })();

  // ---------- LEVEL TABS ----------
  const tabs = document.querySelectorAll(".lvl-tabs button");
  tabs.forEach(btn => btn.addEventListener("click", () => {
    tabs.forEach(b => b.setAttribute("aria-selected", b === btn ? "true" : "false"));
    document.querySelectorAll(".lvl-panel").forEach(p => p.classList.toggle("show", p.id === btn.getAttribute("aria-controls")));
  }));

  // ---------- STICKY NAV ACTIVE STATE ----------
  const navLinks = [...document.querySelectorAll(".sectionnav a")];
  const targets = navLinks.map(a => document.querySelector(a.getAttribute("href"))).filter(Boolean);
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver(entries => {
      entries.forEach(en => {
        if (en.isIntersecting) {
          navLinks.forEach(a => a.classList.toggle("active", a.getAttribute("href") === "#" + en.target.id));
        }
      });
    }, { rootMargin: "-45% 0px -50% 0px" });
    targets.forEach(t => io.observe(t));
  }

  // ---------- MOBILE NAV: edge fades + keep the active link in view ----------
  (function () {
    const snav = document.querySelector(".sectionnav");
    if (!snav) return;
    const fades = () => {
      const max = snav.scrollWidth - snav.clientWidth;
      snav.classList.toggle("fade-l", max > 4 && snav.scrollLeft > 4);
      snav.classList.toggle("fade-r", max > 4 && snav.scrollLeft < max - 4);
    };
    snav.addEventListener("scroll", fades, { passive: true });
    window.addEventListener("resize", fades);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(fades);
    fades();
    const keep = () => {
      const a = snav.querySelector("a.active");
      if (!a || snav.scrollWidth <= snav.clientWidth + 4) return;
      const r = a.getBoundingClientRect(), n = snav.getBoundingClientRect();
      if (r.left < n.left + 16 || r.right > n.right - 40) snav.scrollBy({ left: r.left - n.left - 20, behavior: "smooth" });
    };
    if ("MutationObserver" in window) {
      const mo = new MutationObserver(keep);
      snav.querySelectorAll("a").forEach(a => mo.observe(a, { attributes: true, attributeFilter: ["class"] }));
    }
  })();
})();
